-- Fyrirlestur „Innri kviðfita og insúlínviðnám“ (hc_lectures, kind slides).
-- Attached to plans via hc_plan_templates 'hiit-styrkur' (migration-hc-training-program.sql).
-- Idempotent: upsert on slug. Edit afterwards in /admin/lectures.
insert into public.hc_lectures (slug, title, subtitle, kind, slides, duration_min, pillar, is_welcome, sort, published)
values ('innri-kvidfita', 'Innri kviðfita og insúlínviðnám', 'Hvað skiptir mestu máli – sjö þættir frá grunni og upp', 'slides',
  '[{"layout": "text", "title": "Innri kviðfita og insúlínviðnám", "body": "Hvað skiptir mestu máli og hvar byrjar þú?\n\nInnblástur: hlaðvarp Dave Asprey (þættir 1543 og 1545), aðlagað að ráðleggingum Lifeline Health."}, {"layout": "stat", "stat": "1", "title": "hugtak í miðjunni: insúlínviðnám og innri kviðfita", "body": "Innri kviðfita liggur utan um líffærin í kviðarholinu. Hún tengist insúlínviðnámi, háum blóðþrýstingi og hjarta- og æðasjúkdómum. Þetta sést ekki alltaf á vigtinni."}, {"layout": "bullets", "title": "Hvað hefur mest áhrif?", "body": "Sjö þættir, frá grunni og upp. Þeir fyrstu eru forsenda hinna.", "items": ["Ró: minni streita og góð tengsl", "Svefn", "Styrktarþjálfun", "Kuldi", "Stuttar, ákafar æfingar (HIIT)", "Minna af gjörunnum mat og sykri", "Prótein í hverri máltíð"]}, {"layout": "bullets", "title": "1 · Streita: stærsta hindrunin", "body": "Kortisól er streituhormón sem á að hjálpa okkur í bráðri hættu. Þegar áreiti kveikir á því oft á dag, án líkamlegrar losunar, helst það hátt. Langvarandi hátt kortisól:", "items": ["ýtir undir söfnun innri kviðfitu", "brýtur niður vöðva", "eykur insúlínviðnám"]}, {"layout": "tip", "title": "Ró í dag – og til lengri tíma", "body": "Í dag: 10 mínútna hugleiðsla eða kassaöndun (anda inn 4 sek., halda 4, anda út 4, halda 4).\nTil lengri tíma: fækka streituvöldum, rækta tengsl við aðra, gefa af tíma sínum og hafa tilgang."}, {"layout": "bullets", "title": "2 · Svefn: forsenda alls annars", "body": "Í djúpsvefni losnar vaxtarhormón sem tekur þátt í að nýta fitu sem orku.", "items": ["Lélegur svefn dregur úr vaxtarhormóni og hækkar kortisól", "Mataræði og hreyfing bæta ekki upp fyrir lélegan svefn", "Sami háttatími og sami fótaferðartími alla daga"]}, {"layout": "tip", "title": "Betri svefn", "body": "Fastur fótaferðartími, líka um helgar. Dimmt og svalt svefnherbergi. Síðasta máltíð þremur tímum fyrir svefn.\nSumum hjálpar magnesíum. Ræddu það við lækninn."}, {"layout": "bullets", "title": "3 · Styrktarþjálfun: verðmætasti vefurinn", "body": "Stærsti ávinningur vöðva er ekki útlitið. Vöðvar eru sá vefur líkamans sem notar mesta orku, líka í hvíld.", "items": ["Þung átök valda örsmáum rifum í vöðvaþráðum", "Viðgerðin krefst orku eftir æfinguna og próteins sem byggingarefnis", "Stórir vöðvahópar: hnébeygja, réttstöðulyfta, að ýta og toga", "3 sinnum í viku, krefjandi en með góðri tækni"]}, {"layout": "bullets", "title": "4 · Kuldi", "body": "Líkaminn þarf að framleiða hita til að halda líkamshitanum stöðugum og notar til þess orku.", "items": ["Áhrifin fara eftir skammti: reglulegt skilar meiru en stöku sinnum", "Byrjaðu rólega: 30–60 sekúndur í kaldri sturtu", "Ekki fyrir þau sem eru með hjartasjúkdóm eða háan blóðþrýsting nema í samráði við lækni"]}, {"layout": "stat", "stat": "10–20 mín.", "title": "5 · HIIT, 3 sinnum í viku", "body": "Stuttar, ákafar lotur með hvíld á milli. Þær losa adrenalín og vaxtarhormón sem virkja fitu sem orkugjafa, og orkunotkunin heldur áfram eftir að æfingu lýkur."}, {"layout": "bullets", "title": "6 · Minna af gjörunnum mat og sykri", "body": "Insúlín gefur líkamanum boð um að geyma orku. Mikill sykur og gjörunninn matur halda insúlíninu háu.", "items": ["Minna af sætum drykkjum, sælgæti og kexi", "Minna af gjörunnum mat", "Meira af grænmeti og ávöxtum"]}, {"layout": "stat", "stat": "20–30%", "title": "7 · Prótein í hverri máltíð", "body": "af orku próteins fer í að melta það. Prótein er líka byggingarefni vöðvanna. Egg, kjöt og fiskur."}, {"layout": "bullets", "title": "Ferlið í heild", "items": ["Mataræðið (6 og 7) skapar réttu skilyrðin", "HIIT (5) kveikir á vélinni", "Kuldi (4) kostar orku", "Vöðvar (3) eru verðmætasti vefurinn", "Svefn (2) er forsenda alls", "Ró (1) opnar fyrir allt hitt"]}, {"layout": "bullets", "title": "Næstu skref", "items": ["Æfingaáætlun: HIIT og styrkur þrisvar í viku. Byrjendur fá aðlögun og álagið eykst á 3 mánaða fresti.", "Þú stillir álagið sjálf/ur og lætur vita af meiðslum í öxl, hné eða baki.", "Áætlunin þín er í heilsuferðinni, undir Áætlun.", "Endurmæling sýnir hvernig gengur."]}]'::jsonb, 25, 'general', false, 60, true)
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, kind = excluded.kind,
  slides = excluded.slides, duration_min = excluded.duration_min, pillar = excluded.pillar, published = true;
